program='''def transform(grid):
    h, w = len(grid), len(grid[0])
    values = {v for row in grid for v in row if v != 0}
    if not values:
        return [row[:] for row in grid]

    # The picture is a repeating one-dimensional color sequence placed on
    # parallel rows/columns/diagonals. Find the shortest modular phase pattern
    # that agrees with every nonzero clue.
    for period in range(len(values), max(h, w) + 1):
        best = None
        for a in range(period):
            for b in range(period):
                phase_colors = {}
                valid = True
                for r in range(h):
                    for c in range(w):
                        color = grid[r][c]
                        if color:
                            phase = (a * r + b * c) % period
                            if phase in phase_colors and phase_colors[phase] != color:
                                valid = False
                                break
                            phase_colors[phase] = color
                    if not valid:
                        break
                if valid:
                    candidate = (len(phase_colors), -a, -b, phase_colors, a, b)
                    if best is None or candidate[:3] > best[:3]:
                        best = candidate
        if best is not None:
            _, _, _, phase_colors, a, b = best
            fallback = next(iter(phase_colors.values()))
            return [[phase_colors.get((a*r+b*c) % period, fallback)
                     for c in range(w)] for r in range(h)]

    # Defensive fallback: copy the nearest known row color where possible.
    return [[grid[r][c] if grid[r][c] else next((grid[rr][c] for rr in range(h) if grid[rr][c]), 0)
             for c in range(w)] for r in range(h)]
